import{_ as r,o as n,c as i,ah as t}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Der Kreis schließt sich: René Benko und das Erbe der Hortens","description":"Wir verknüpfen die Signa-Pleite mit der historischen Arisierung. René Benko als moderner Nachfahre im Horten-Mysterium.","frontmatter":{"title":"Der Kreis schließt sich: René Benko und das Erbe der Hortens","description":"Wir verknüpfen die Signa-Pleite mit der historischen Arisierung. René Benko als moderner Nachfahre im Horten-Mysterium.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-benko-verbindung.md","filePath":"logbuch/2026-02-27-benko-verbindung.md"}'),s={name:"logbuch/2026-02-27-benko-verbindung.md"};function o(a,e,d,l,h,u){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="der-kreis-schließt-sich-rene-benko-und-das-erbe-der-hortens" tabindex="-1">Der Kreis schließt sich: René Benko und das Erbe der Hortens <a class="header-anchor" href="#der-kreis-schließt-sich-rene-benko-und-das-erbe-der-hortens" aria-label="Permalink to &quot;Der Kreis schließt sich: René Benko und das Erbe der Hortens&quot;">​</a></h1><p>Ein Projekt über Helmut Horten wäre heute unvollständig, ohne den Namen René Benko zu nennen. Warum? Weil Benko der Mann ist, der die Warenhäuser, die einst Horten gehörten, in die größte Pleite der österreichischen Geschichte geführt hat.</p><p><strong>Unsere narrativen Verknüpfungen:</strong></p><ul><li><strong>Vom Blut zum Beton:</strong> Horten baute auf dem Leid der Arisierungsopfer (Alsberg). Benko baute auf den Immobilien dieser Häuser.</li><li><strong>Der spekulatve Pointillismus:</strong> Benko ist der Meister der Bewertung. Viele kleine, künstlich erhöhte Immobilienwerte ergaben am Ende ein fiktives Milliarden-Mosaik.</li><li><strong>Die politische Achse:</strong> Sowohl Horten als auch Benko pflegten engste Kontakte zur ÖVP-Spitze (insbesondere zur Ära Kurz).</li></ul><p>Benko wird im Drehbuch als die tragisch-groteske Figur eingeführt, die versucht, das Schweigen der Hortens durch das Lärmen der Baustellen zu ersetzen – und am Ende in der Stille der Insolvenz landet.</p><p><em>Dokumentiert von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',6)])])}const g=r(s,[["render",o]]);export{m as __pageData,g as default};
